// TestCreateRedactedBlobFromFile_RedactsContentContainingNUL is the regression
// test for the fail-open binary sniff: go-git's binary.IsBinary returns true on
// the first single 0x00 byte in the first 8000, so one NUL anywhere near the
// head of a metadata file used to send the whole file to git verbatim — no
// redaction at all — on the shadow branch that `git push --all`/`--mirror`
// ships.
func TestCreateRedactedBlobFromFile_RedactsContentContainingNUL(t *testing.T) {
	t.Parallel()

	tempDir := t.TempDir()
	testutil.InitRepo(t, tempDir)
	repo, err := git.PlainOpen(tempDir)
	require.NoError(t, err)

	sessionDir := filepath.Join(tempDir, "metadata")
	require.NoError(t, os.MkdirAll(sessionDir, 0o750))

	// A JSONL transcript whose first line carries a raw NUL (an agent writing a
	// control byte straight into its rollout) and whose second line carries a
	// credential. Strict JSON escapes NUL as �, so this shape needs an
	// agent that emits raw control bytes — but the whole file is what gets
	// exempted, so one such line disables redaction for every other line.
	transcript := "{\"type\":\"user\",\"content\":\"hello\x00world\"}\n" +
		`{"type":"assistant","content":"export TOKEN=` + highEntropySecret + `"}` + "\n"
	require.NoError(t, os.WriteFile(filepath.Join(sessionDir, paths.TranscriptFileName), []byte(transcript), 0o600))

	// prompt.txt is plain text, so a NUL there is more plausible still.
	prompt := "paste of a build log\x00 with API_KEY=" + highEntropySecret + "\n"
	require.NoError(t, os.WriteFile(filepath.Join(sessionDir, paths.PromptFileName), []byte(prompt), 0o600))

	treePrefix := paths.EntireMetadataDir + "/nul-session"
	changes, err := addDirectoryToChanges(context.Background(), repo, nil, sessionDir, treePrefix)
	require.NoError(t, err)
	require.Len(t, changes, 2)

	for _, change := range changes {
		require.NotNil(t, change.Entry, "change %s has no entry", change.Path)
		content := blobText(t, repo, *change.Entry)
		require.NotContains(t, content, highEntropySecret,
			"%s reached the git blob with the credential intact", change.Path)
		require.Contains(t, content, redact.RedactedPlaceholder,
			"%s should carry a redaction placeholder", change.Path)
	}
}

